 const item={version:1,source:calendarCacheSource(),savedAt:Date.now(),events:E,stateEvents:SE,calendarState,calendarWarning,stateEventState,stateEventWarning};
 try{localStorage.setItem(CALENDAR_CACHE_KEY,JSON.stringify(item))}catch(_){/* Private browsing or storage quotas: keep working without a cache. */}
