async function loadCoverSettings(){if(!CFG.apiBase||!document.querySelector('[data-cover]'))return;try{const r=await fetchWithTimeout(CFG.apiBase.replace(/\/$/, '')+'/api/covers',{headers:{Accept:'application/json'}},4500);if(!r.ok)return;const d=await r.json();coverMap=d.covers&&typeof d.covers==='object'?d.covers:{};applyCoverBackgrounds()}catch(e){console.info('Banner covers are not connected yet.') }}
function applyCoverBackgrounds(){
 const base=String(CFG.apiBase||'').replace(/\/$/,'');
 document.querySelectorAll('[data-cover]').forEach(el=>{
  const key=el.dataset.cover,c=coverMap[key];
  if(!base||!c)return;
  const image=`${base}/api/covers/${key}?v=${encodeURIComponent(c.updatedAt||'')}`;
  if(!/^https:\/\//i.test(image)||el.dataset.apiCoverRequest===image)return;
  el.dataset.apiCoverRequest=image;
  const probe=new Image();
  const apply=()=>{
   if(!el.isConnected||el.dataset.apiCoverRequest!==image)return;
   const video=el.querySelector(':scope > .cover-media-video');
   if(video){if(video._coverObserver)video._coverObserver.disconnect();try{video.pause()}catch(_){}video.remove()}
   el.style.setProperty('--cover-image',`url(${JSON.stringify(image)})`);
   el.dataset.coverPhotoSource='api';delete el.dataset.localBannerPhoto;
  };
  probe.onload=apply;
  probe.onerror=()=>{if(el.dataset.apiCoverRequest===image)delete el.dataset.apiCoverRequest;console.info('An optional banner cover could not be loaded; keeping the local banner instead.')};
  probe.src=image;if(probe.complete&&probe.naturalWidth>0)apply();
 });
}
